from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from time import perf_counter
from typing import Dict, List, Mapping, Protocol, Tuple

TARGET_PRIMARY_QUALITY = Decimal("0.75")
MAX_ITERATIONS = 3
_CENTS = Decimal("0.01")


class RepairFn(Protocol):
    def __call__(self, current_module: str, feedback: Dict[str, object]) -> str:
        ...


class VerifyFn(Protocol):
    def __call__(self, candidate_module: str) -> Mapping[str, object]:
        """Return a result with at least:
        - primary_quality: number-like value in [0.0, 1.0]
        - passed: optional bool-like value
        - diagnostics: optional list[str] or str
        - optional monetary keys: money_spent_usd | money_spent | cost_usd | cost
        """


@dataclass
