    iteration: int
    primary_quality: float
    passed: bool
    elapsed_ms: int
    diagnostics: List[str] = field(default_factory=list)
    candidate_module: str = ""
    money_spent_cents: int = 0


@dataclass
class RepairLoopReport:
    success: bool
    best_module: str
    best_primary_quality: float
    iterations_run: int
    history: List[IterationResult]
    total_money_spent_cents: int = 0


def _normalize_diagnostics(value: object) -> List[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(item) for item in value]
    return [str(value)]


def _to_decimal(value: object, *, key: str) -> Decimal:
    try:
        if isinstance(value, Decimal):
            out = value
        elif isinstance(value, (int, str)):
            out = Decimal(str(value))
        elif isinstance(value, float):
            out = Decimal(str(value))
        else:
            raise TypeError
    except (InvalidOperation, TypeError):
        raise ValueError(f"Invalid {key}: {value!r}") from None

    if not out.is_finite():
        raise ValueError(f"{key} must be finite: {value!r}")
    return out


def _coerce_bool(value: object, *, default: bool) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"true", "1", "yes", "y", "pass", "passed"}:
            return True
        if lowered in {"false", "0", "no", "n", "fail", "failed"}:
            return False
    raise ValueError(f"Invalid passed value: {value!r}")


def _extract_money_spent_cents(raw: Mapping[str, object]) -> int:
    for key in ("money_spent_usd", "money_spent", "cost_usd", "cost"):
