            amount = _to_decimal(raw[key], key=key)
            if amount < 0:
                raise ValueError(f"{key} cannot be negative: {raw[key]!r}")
            cents = (amount.quantize(_CENTS) * 100).to_integral_value()
            return int(cents)
    return 0


