def build_intervals(
    intervals: Optional[Sequence[float] | float],
    max_iterations: int,
) -> List[float]:
    """
    Build one delay value per iteration index (length == max_iterations).

    Rules:
    - None -> all zeros
    - scalar -> repeated
    - empty sequence -> all zeros
    - short sequence -> pad with last value
    - long sequence -> truncate
    """
    if max_iterations <= 0:
