    metrics: Dict[str, float] = field(default_factory=dict)

    def normalized(self) -> "IterationResult":
        pq = max(0.0, min(1.0, float(self.primary_quality)))
        return IterationResult(primary_quality=pq, diagnostics=self.diagnostics, metrics=self.metrics)


@dataclass(frozen=True)
class LoopConfig:
    target_quality: float = 0.75
    max_iterations: int = 3

    def normalized(self) -> "LoopConfig":
        tq = max(0.0, min(1.0, float(self.target_quality)))
        mi = max(1, int(self.max_iterations))
        return LoopConfig(target_quality=tq, max_iterations=mi)


@dataclass
class LoopOutcome:
    final_source: str
    reached_target: bool
    iterations_used: int
    final_result: IterationResult
    history: List[IterationResult]


def run_repair_loop(
    initial_source: str,
    evaluate: EvaluateFn,
    repair: RepairFn,
    config: Optional[LoopConfig] = None,
) -> LoopOutcome:
    """Run up to `max_iterations` repair passes, stopping early when quality target is met."""
    cfg = (config or LoopConfig()).normalized()

    source = initial_source
    history: List[IterationResult] = []

    # Baseline evaluation before any repair pass.
    baseline = evaluate(source).normalized()
    history.append(baseline)
    if baseline.primary_quality >= cfg.target_quality:
        return LoopOutcome(
            final_source=source,
            reached_target=True,
            iterations_used=0,
            final_result=baseline,
            history=history,
        )

    current = baseline
    for iteration in range(1, cfg.max_iterations + 1):
        source = repair(source, current, iteration)
        current = evaluate(source).normalized()
        history.append(current)

        if current.primary_quality >= cfg.target_quality:
            return LoopOutcome(
                final_source=source,
                reached_target=True,
                iterations_used=iteration,
                final_result=current,
                history=history,
            )

    return LoopOutcome(
        final_source=source,
        reached_target=False,
        iterations_used=cfg.max_iterations,
        final_result=current,
        history=history,
    )


def format_outcome(outcome: LoopOutcome) -> str:
    """Human-readable summary useful for CI logs."""
    status = "PASS" if outcome.reached_target else "FAIL"
    lines = [
        f"[{status}] primary_quality={outcome.final_result.primary_quality:.3f} "
        f"target>=0.750 iterations={outcome.iterations_used}",
    ]
    for idx, result in enumerate(outcome.history):
