def _coerce_quality(metrics: Mapping[str, Any]) -> float:
    raw = metrics.get("primary_quality", 0.0)
    try:
        quality = float(raw)
    except (TypeError, ValueError):
        return 0.0

    if quality < 0.0:
        return 0.0
    if quality > 1.0:
        return 1.0
    return quality


def run_repair_loop(
    module_text: str,
    evaluator: Evaluator,
    repairer: Repairer,
    target_quality: float = 0.75,
    max_iterations: int = 3,
) -> RepairLoopResult:
    """
    Evaluate -> (optional) repair loop.

    Behavior:
    - Evaluates at most `max_iterations` times.
    - Stops early when primary_quality >= target_quality.
    - Repairs only between iterations (never after the final evaluation interval).
    """
    if not isinstance(module_text, str):
        raise TypeError("module_text must be a string")
    if not callable(evaluator):
        raise TypeError("evaluator must be callable")
    if not callable(repairer):
        raise TypeError("repairer must be callable")
    if not isinstance(max_iterations, int) or max_iterations < 1:
        raise ValueError("max_iterations must be an integer >= 1")
    if not (0.0 <= target_quality <= 1.0):
        raise ValueError("target_quality must be within [0.0, 1.0]")

    current = module_text
    history: List[IterationResult] = []

    for i in range(1, max_iterations + 1):
        metrics = evaluator(current)
        quality = _coerce_quality(metrics)
        passed = quality >= target_quality

        history.append(
            IterationResult(
                iteration=i,
                primary_quality=quality,
                passed=passed,
                notes=str(metrics.get("notes", "")),
            )
        )

        if passed:
            return RepairLoopResult(
                success=True,
                final_module=current,
                iterations_used=i,
                history=tuple(history),
            )

        # No extra repair after the last evaluation interval.
        if i < max_iterations:
            next_module = repairer(current, metrics)
            if not isinstance(next_module, str):
                raise TypeError("repairer must return a string module")
            current = next_module

    return RepairLoopResult(
        success=False,
        final_module=current,
        iterations_used=max_iterations,
        history=tuple(history),
    )


def repair_loop(
    module_text: str,
    evaluator: Evaluator,
    repairer: Repairer,
    target_quality: float = 0.75,
    max_iterations: int = 3,
) -> Dict[str, Any]:
    """
    Compatibility wrapper returning a plain dict.
    """
    result = run_repair_loop(
        module_text=module_text,
        evaluator=evaluator,
        repairer=repairer,
        target_quality=target_quality,
        max_iterations=max_iterations,
    )
    return {
        "success": result.success,
        "final_module": result.final_module,
        "iterations_used": result.iterations_used,
        "history": [
            {
                "iteration": row.iteration,
                "primary_quality": row.primary_quality,
                "passed": row.passed,
                "notes": row.notes,
            }
            for row in result.history
        ],
    }


