import math
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Mapping, Protocol, Tuple


class QualityEvaluator(Protocol):
    """Callable protocol for scoring candidate code/modules."""

    def __call__(self, candidate: str) -> Mapping[str, float]:
        """
        Return metric mapping containing at least:
          - 'primary_quality': float in [0.0, 1.0]
        """


RepairFn = Callable[[str, Dict[str, float], int], str]


@dataclass(frozen=True)
class IterationResult:
    iteration: int
    candidate: str
    metrics: Dict[str, float]


@dataclass(frozen=True)
class RepairSummary:
    initial_candidate: str
    best_candidate: str
    best_metrics: Dict[str, float]
    target_quality: float
    max_iterations: int
    reached_target: bool
    iterations_run: int
    history: Tuple[IterationResult, ...] = field(default_factory=tuple)


class RepairLoopError(ValueError):
    pass


def _coerce_and_validate_metrics(
    metrics: Mapping[str, float], *, context: str
) -> Dict[str, float]:
    if not isinstance(metrics, Mapping):
        raise RepairLoopError(
            f"{context}: evaluator must return a mapping, got {type(metrics).__name__}."
        )

    if "primary_quality" not in metrics:
        raise RepairLoopError(
            f"{context}: evaluator must return 'primary_quality' in metrics."
        )

    value = metrics["primary_quality"]
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise RepairLoopError(
            f"{context}: 'primary_quality' must be numeric, got {type(value).__name__}."
        )

    value = float(value)
    if not math.isfinite(value):
        raise RepairLoopError(
            f"{context}: 'primary_quality' must be finite, got {value}."
        )
    if value < 0.0 or value > 1.0:
        raise RepairLoopError(
            f"{context}: 'primary_quality' must be within [0.0, 1.0], got {value}."
        )

    return dict(metrics)


def run_repair_loop(
    module_text: str,
    evaluator: QualityEvaluator,
    repair_fn: RepairFn,
    *,
    target_quality: float = 0.75,
    max_iterations: int = 3,
) -> RepairSummary:
    """
    Fast-verify repair loop:
      1) score current candidate
      2) apply repair
      3) re-score
    Stops early when primary_quality >= target_quality, with an upper bound
    of max_iterations repair attempts.
    """
    if not isinstance(module_text, str) or not module_text.strip():
        raise RepairLoopError("module_text must be a non-empty string.")
    if not callable(evaluator):
        raise RepairLoopError("evaluator must be callable.")
    if not callable(repair_fn):
        raise RepairLoopError("repair_fn must be callable.")
    if not isinstance(max_iterations, int) or isinstance(max_iterations, bool):
        raise RepairLoopError("max_iterations must be an integer.")
    if max_iterations < 1:
        raise RepairLoopError("max_iterations must be >= 1.")
    if isinstance(target_quality, bool) or not isinstance(target_quality, (int, float)):
        raise RepairLoopError("target_quality must be numeric.")
    target_quality = float(target_quality)
    if not math.isfinite(target_quality) or not (0.0 <= target_quality <= 1.0):
        raise RepairLoopError("target_quality must be within [0.0, 1.0].")

    history: List[IterationResult] = []

    current_candidate = module_text
    current_metrics = _coerce_and_validate_metrics(
        evaluator(current_candidate), context="initial evaluation"
    )
    history.append(
        IterationResult(
            iteration=0, candidate=current_candidate, metrics=dict(current_metrics)
        )
    )

    best_candidate = current_candidate
    best_metrics = dict(current_metrics)

    if best_metrics["primary_quality"] >= target_quality:
        return RepairSummary(
            initial_candidate=module_text,
            best_candidate=best_candidate,
            best_metrics=best_metrics,
            target_quality=target_quality,
            max_iterations=max_iterations,
            reached_target=True,
            iterations_run=0,
            history=tuple(history),
        )

    for i in range(1, max_iterations + 1):
        repaired = repair_fn(current_candidate, dict(current_metrics), i)
        if not isinstance(repaired, str) or not repaired.strip():
            raise RepairLoopError(
                f"repair_fn produced invalid candidate at iteration {i}."
            )

        current_candidate = repaired
        current_metrics = _coerce_and_validate_metrics(
            evaluator(current_candidate), context=f"iteration {i}"
        )
        history.append(
            IterationResult(
                iteration=i, candidate=current_candidate, metrics=dict(current_metrics)
            )
        )

        if current_metrics["primary_quality"] > best_metrics["primary_quality"]:
            best_candidate = current_candidate
            best_metrics = dict(current_metrics)

        if current_metrics["primary_quality"] >= target_quality:
            return RepairSummary(
                initial_candidate=module_text,
                best_candidate=best_candidate,
                best_metrics=best_metrics,
                target_quality=target_quality,
                max_iterations=max_iterations,
                reached_target=True,
                iterations_run=i,
                history=tuple(history),
            )

    return RepairSummary(
        initial_candidate=module_text,
        best_candidate=best_candidate,
        best_metrics=best_metrics,
        target_quality=target_quality,
        max_iterations=max_iterations,
        reached_target=False,
        iterations_run=max_iterations,
        history=tuple(history),
    )


def default_repair_fn(candidate: str, metrics: Dict[str, float], iteration: int) -> str:
    """
    Conservative no-op fallback.
    Replace this with a domain-specific repair strategy.
    """
    _ = (metrics, iteration)
    return candidate


def get_primary_quality(summary: RepairSummary) -> float:
