from __future__ import annotations

from dataclasses import dataclass
from time import perf_counter
from typing import Callable, Dict, List, Mapping, Optional


TARGET_PRIMARY_QUALITY = 0.75
MAX_ITERATIONS = 3


@dataclass(frozen=True)
class IterationResult:
    iteration: int
    module_text: str
    metrics: Dict[str, object]
    primary_quality: float
    passed: bool
    duration_seconds: float


@dataclass(frozen=True)
class RepairResult:
    converged: bool
    target_quality: float
    max_iterations: int
    best: IterationResult
    history: List[IterationResult]
    total_duration_seconds: float


class RepairLoopError(RuntimeError):
    """Raised when the repair loop receives invalid evaluator output."""


def _as_float(value: object, *, metric_name: str) -> float:
    if isinstance(value, bool):
        value = float(value)
    if not isinstance(value, (int, float)):
        raise RepairLoopError(f"Metric '{metric_name}' must be numeric, got {type(value).__name__}.")
    return float(value)


def _to_unit_interval(value: object, *, metric_name: str) -> float:
    score = _as_float(value, metric_name=metric_name)
    if score < 0.0:
        return 0.0
    if score > 1.0:
        return 1.0
    return score


def extract_primary_quality(metrics: Mapping[str, object]) -> float:
    """
    Robustly extract a quality score from evaluator metrics.

    Accepted keys (first match wins):
    - 'primary_quality'
    - 'quality'
    - 'score'

    Key matching is case-insensitive.
    """
    direct_keys = ("primary_quality", "quality", "score")
    for key in direct_keys:
        if key in metrics:
            return _to_unit_interval(metrics[key], metric_name=key)

    lower_lookup = {str(k).lower(): k for k in metrics.keys()}
    for key in direct_keys:
        if key in lower_lookup:
            original_key = lower_lookup[key]
            return _to_unit_interval(metrics[original_key], metric_name=str(original_key))

    raise RepairLoopError(
        "Evaluator metrics must include one of: 'primary_quality', 'quality', or 'score'."
    )


def default_fast_verify(module_text: str) -> Dict[str, float]:
    """
    Lightweight verifier for offline use.
    Produces a primary_quality score in [0, 1].
    """
    score = 0.0

    # 1) Syntax validity (high weight)
    try:
        compile(module_text, "<candidate_module>", "exec")
        score += 0.55
    except SyntaxError:
        return {"primary_quality": 0.0, "syntax_ok": 0.0}

    # 2) Basic structure heuristics
    stripped = module_text.strip()
    if stripped:
        score += 0.10
    if "def " in module_text or "class " in module_text:
        score += 0.15
    if "TODO" not in module_text and "pass" not in module_text:
        score += 0.10
    if len(module_text.splitlines()) >= 8:
        score += 0.10

    return {
        "primary_quality": _to_unit_interval(score, metric_name="primary_quality"),
        "syntax_ok": 1.0,
    }


def run_repair_loop(
    initial_module: str,
    propose_candidate: Callable[[str, int, Optional[IterationResult]], str],
    verify_candidate: Callable[[str], Mapping[str, object]] = default_fast_verify,
    *,
    target_quality: float = TARGET_PRIMARY_QUALITY,
    max_iterations: int = MAX_ITERATIONS,
) -> RepairResult:
    """
    Fast-verify repair loop:
    - evaluates each candidate
    - stops as soon as primary_quality >= target_quality
    - guarantees at most `max_iterations` evaluations

    proposer contract:
    - called only after a failed evaluation
    - receives (current_module_text, failed_iteration_index, failed_result)
    - must return next module_text as str
    """
    if not isinstance(initial_module, str):
        raise TypeError("initial_module must be a string.")
    if not (0.0 <= target_quality <= 1.0):
        raise ValueError("target_quality must be between 0.0 and 1.0.")
    if max_iterations < 1:
        raise ValueError("max_iterations must be >= 1.")

    history: List[IterationResult] = []
    current_candidate = initial_module
    best_result: Optional[IterationResult] = None
    total_duration_seconds = 0.0

    for iteration in range(1, max_iterations + 1):
        started = perf_counter()
        raw_metrics = verify_candidate(current_candidate)
        duration_seconds = perf_counter() - started
        total_duration_seconds += duration_seconds

        if not isinstance(raw_metrics, Mapping):
            raise RepairLoopError(
                f"verify_candidate must return a mapping, got {type(raw_metrics).__name__}."
            )

        metrics = dict(raw_metrics)
        primary_quality = extract_primary_quality(metrics)
        passed = primary_quality >= target_quality

        if "duration_seconds" not in metrics:
            metrics["duration_seconds"] = duration_seconds

        result = IterationResult(
            iteration=iteration,
            module_text=current_candidate,
            metrics=metrics,
            primary_quality=primary_quality,
            passed=passed,
            duration_seconds=duration_seconds,
        )
        history.append(result)

        if (
            best_result is None
            or result.primary_quality > best_result.primary_quality
            or (
                result.primary_quality == best_result.primary_quality
                and result.iteration < best_result.iteration
            )
        ):
            best_result = result

        if passed:
            return RepairResult(
                converged=True,
                target_quality=target_quality,
                max_iterations=max_iterations,
                best=result,
                history=history,
                total_duration_seconds=total_duration_seconds,
            )

        if iteration < max_iterations:
            next_candidate = propose_candidate(current_candidate, iteration, result)
            if not isinstance(next_candidate, str):
                raise RepairLoopError(
                    f"propose_candidate must return a string, got {type(next_candidate).__name__}."
                )
            current_candidate = next_candidate

    if best_result is None:
        # Defensive fallback for static analyzers and impossible runtime path.
        raise RepairLoopError("Repair loop completed without any iteration results.")

    return RepairResult(
        converged=False,
        target_quality=target_quality,
        max_iterations=max_iterations,
        best=best_result,
        history=history,
        total_duration_seconds=total_duration_seconds,
    )


# Optional convenience alias with the objective defaults.
fast_verify_repair_loop = run_repair_loop
